import{_ as s,C as n,o as e,c as d,j as i,E as o,a as t,a3 as r}from"./chunks/framework.C6R8kWFE.js";const T=JSON.parse(`{"title":"7-dars (Mentor). Photoshop interfeysi va vositalari (3-qism): Qatlamlar bilan amaliy ishlash va assetlar kollaji","description":"","frontmatter":{"title":"7-dars (Mentor). Photoshop interfeysi va vositalari (3-qism): Qatlamlar bilan amaliy ishlash va assetlar kollaji","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":3,"link":"/mentor/9-sinf-game/hafta-03/"},"g":7,"title":"Photoshop interfeysi va vositalari (3-qism): Qatlamlar bilan amaliy ishlash va assetlar kollaji","lead":"Photoshop interfeysi va vositalari (3-qism): Qatlamlar bilan amaliy ishlash va assetlar kollaji","slide":"/slaydlar/9-sinf-game/hafta-03/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-03/dars-1-test.html","student_link":"/9-sinf-game/hafta-03/dars-1","tabs":[{"g":7,"link":"/mentor/9-sinf-game/hafta-03/dars-1","current":true},{"g":8,"link":"/mentor/9-sinf-game/hafta-03/dars-2","current":false},{"g":9,"link":"/mentor/9-sinf-game/hafta-03/dars-3","current":false}],"prev":null,"next":{"g":8,"title":"Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK, rang g'ildiragi va rang psixologiyasi","link":"/mentor/9-sinf-game/hafta-03/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-03/dars-1.md","filePath":"mentor/9-sinf-game/hafta-03/dars-1.md"}`),h={name:"mentor/9-sinf-game/hafta-03/dars-1.md"},m={class:"blk"},g={id:"dars-rejasi",tabindex:"-1"},u={class:"blk"},y={id:"mentor-konspekti",tabindex:"-1"},q={class:"blk"},c={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},k={class:"blk"},b={id:"tezkor-nazorat-savollari",tabindex:"-1"},p={class:"blk"},v={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function f(_,a,j,x,z,C){const l=n("Icon");return e(),d("div",null,[i("div",m,[i("h2",g,[o(l,{name:"file-text"}),a[0]||(a[0]=t(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=r("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga Photoshop dasturida qatlamlar (Layers) panelining ilg&#39;or imkoniyatlarini (qurshov maskalari — Clipping Masks, Smart Objects, qatlamlarni guruhlash va qulflash) chuqur o&#39;rgatish hamda turli xil tayyor 2D o&#39;yin elementlaridan (qahramon, dushmanlar, platforma, fon va yorug&#39;lik) uyg&#39;un va yaxlit o&#39;yin sahnasi kollajini (Game Scene Collage) yig&#39;ish ko&#39;nikmasini shakllantirish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar ko&#39;p qatlamli fayllarni tartibga solishni (guruhlar, rangli yorliqlar) biladi; Smart Object xususiyatini tushunib, assetlarni sifat yo&#39;qotmasdan masshtablay oladi; Clipping Mask yordamida obyekt chegarasidan chiqmagan holda teksturalar ulaydi; yakuniy o&#39;yin sahnasi kollajini to&#39;liq yig&#39;a oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (Tanlash vositalari, Layer Masks, Blending Modes): 10 daqiqa</li><li>Yangi mavzu: Qatlamlarni tashkil etish, Smart Objects va Clipping Masks: 25 daqiqa</li><li>Amaliy mashg&#39;ulot: O&#39;yin darajasi (Level Art) kollajini yaratish: 30 daqiqa</li><li>Amaliyot tahlili va keng tarqalgan xatolar: 10 daqiqa</li><li>Dars xulosasi va tezkor savol-javob: 5 daqiqa</li></ul></li></ul><hr>",2))]),i("div",u,[i("h2",y,[o(l,{name:"file-text"}),a[3]||(a[3]=t(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=r('<h3 id="_1-ko-p-qatlamli-o-yin-loyihalarida-tartib-va-arxitektura" tabindex="-1">1. Ko&#39;p qatlamli o&#39;yin loyihalarida tartib va arxitektura <a class="header-anchor" href="#_1-ko-p-qatlamli-o-yin-loyihalarida-tartib-va-arxitektura" aria-label="Permalink to &quot;1. Ko&#39;p qatlamli o&#39;yin loyihalarida tartib va arxitektura&quot;">​</a></h3><p>Professional 2D o&#39;yin sahnasi (konsept-art yoki daraja foni) o&#39;nlab, ba&#39;zan yuzlab qatlamlardan iborat bo&#39;ladi. Ularni boshqarish uchun quyidagi qoidalar qo&#39;llaniladi:</p><ol><li><strong>Nomlash madaniyati:</strong> Har bir qatlam o&#39;z mazmuniga ko&#39;ra nomlanishi shart (<code>Hero_Idle</code>, <code>Platform_Grass_01</code>, <code>VFX_Fire_Glow</code>). Standart <code>Layer 1</code>, <code>Layer 2 copy 3</code> kabi nomlar qat&#39;iyan taqiqlanadi.</li><li><strong>Guruhlash (Groups - <code>Ctrl + G</code>):</strong> Qatlamlar mantiqiy papkalarga yig&#39;iladi: <ul><li><code>[04_HUD_UI]</code> — salomatlik paneli, tangalar hisoblagichi, mini-xarita.</li><li><code>[03_Foreground]</code> — qahramon, dushmanlar, interaktiv qutilar.</li><li><code>[02_Midground]</code> — platformalar, zamin tayllari, daraxtlar.</li><li><code>[01_Background]</code> — osmon, bulutlar, uzoq tog&#39;lar silueti.</li></ul></li><li><strong>Qulflash (Locking):</strong> Tasodifiy surilib ketmasligi uchun orqa fon va tayyor platforma qatlamlari <code>Lock</code> (qulf) qilinadi.</li></ol><h3 id="_2-aqlli-obyektlar-smart-objects" tabindex="-1">2. Aqlli obyektlar (Smart Objects) <a class="header-anchor" href="#_2-aqlli-obyektlar-smart-objects" aria-label="Permalink to &quot;2. Aqlli obyektlar (Smart Objects)&quot;">​</a></h3><ul><li><strong>Muammo:</strong> Oddiy rastr qatlamni <code>Ctrl + T</code> bilan 10% gacha kichraytirib, <code>Enter</code> bosilsa, Photoshop piksellarni tashlab yuboradi. Keyin uni qayta 100% ga kattalashtirsangiz, tasvir butunlay loyqa (xira) bo&#39;lib qoladi.</li><li><strong>Yechim (Smart Object):</strong><ul><li>Qatlam ustiga o&#39;ng tugma bosilib, <code>Convert to Smart Object</code> qilinadi.</li><li>Smart Object asl yuqori sifatli faylni o&#39;z konteynerida saqlaydi.</li><li>Uni necha marta kichraytirib-kattalashtirsangiz ham (original o&#39;lcham doirasida) zarracha sifat yo&#39;qolmaydi!</li><li>Smart Objectga qo&#39;llanilgan filtrlar (Blur, Sharpen) ham <code>Smart Filters</code> ga aylanadi va istalgan paytda qayta sozlanadi.</li></ul></li></ul><h3 id="_3-qurshov-niqobi-clipping-mask-ctrl-alt-g" tabindex="-1">3. Qurshov niqobi (Clipping Mask - <code>Ctrl + Alt + G</code>) <a class="header-anchor" href="#_3-qurshov-niqobi-clipping-mask-ctrl-alt-g" aria-label="Permalink to &quot;3. Qurshov niqobi (Clipping Mask - `Ctrl + Alt + G`)&quot;">​</a></h3><ul><li><strong>Tushunchasi:</strong> Yuqori qatlamdagi rasm yoki teksturani faqat pastki qatlam shaklining ichidagina ko&#39;rinadigan qilib bog&#39;lash.</li><li><strong>O&#39;yindagi amaliy qo&#39;llanilishi:</strong><ul><li>Metall qalqon chizilgan. Uning ustiga zanglagan temir teksturasi qo&#39;yildi.</li><li>Agar tekstura qatlamida <code>Create Clipping Mask</code> bosilsa, zang teksturasi qalqon chegarasidan bir millimetr ham tashqariga chiqmaydi!</li><li>Qahramon libosiga soya berish yoki o&#39;yin logotipiga yaltirash (shining) effekti qo&#39;shish uchun eng tezkor usul.</li></ul></li></ul><h3 id="_4-assetlar-kollaji-game-scene-collage-tayyorlash-algoritmi" tabindex="-1">4. Assetlar kollaji (Game Scene Collage) tayyorlash algoritmi <a class="header-anchor" href="#_4-assetlar-kollaji-game-scene-collage-tayyorlash-algoritmi" aria-label="Permalink to &quot;4. Assetlar kollaji (Game Scene Collage) tayyorlash algoritmi&quot;">​</a></h3><ol><li><strong>Canvas yaratish:</strong> 1920x1080 px, 72 DPI, RGB rejimida o&#39;yin kadrini ochish.</li><li><strong>Fonni joylash:</strong> Osmon va uzoq manzarani eng pastki qatlamga joylashtirish.</li><li><strong>Platformalarni terish:</strong> Zamin bloklari va toshlarni joylashtirib, perspektiva va masshtabni to&#39;g&#39;rilash.</li><li><strong>Qahramon va obyektlarni integratsiya qilish:</strong> Qahramon, qurollar va dushmanlarni kompozitsiya markaziga joylash.</li><li><strong>Yorug&#39;lik va soyalar (Light &amp; Shadow):</strong><ul><li>Har bir obyekt ostiga yangi qatlamda <code>Multiply</code> rejimi va 0% Hardness cho&#39;tka bilan soya tushirish.</li><li>Sahna umumiy atmosferasiga mos nur effektlarini <code>Screen</code> qatlamida qo&#39;shish.</li></ul></li><li><strong>Umumiy rang korreksiyasi:</strong> Barcha assetlar turli manbalardan olingani sababli, sahnaning eng ustiga <code>Adjustment Layer</code> (Color Balance yoki Curves) qo&#39;yilib, barcha elementlar yagona rang muhitiga keltiriladi.</li></ol><hr>',10))]),i("div",q,[i("h2",c,[o(l,{name:"file-text"}),a[6]||(a[6]=t(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=r('<h3 id="_1-topshiriq-smart-object-bilan-personajni-himoyalash-oson" tabindex="-1">1-topshiriq. Smart Object bilan personajni himoyalash (oson) <a class="header-anchor" href="#_1-topshiriq-smart-object-bilan-personajni-himoyalash-oson" aria-label="Permalink to &quot;1-topshiriq. Smart Object bilan personajni himoyalash (oson)&quot;">​</a></h3><p>O&#39;yin sahnasiga 500x500 pikselli qahramon sprayti joylashtirildi. Dizayner uni uzoq masofada turgan kichik dushmanga aylantirish uchun o&#39;lchamini 50x50 pikselgacha kichraytirdi, ammo keyingi bosqichda uni yana boshliq (Boss) qahramon sifatida 600x600 pikselgacha kattalashtirishi kerak bo&#39;ldi. Piksellar loyqalanib ketmasligi uchun ushbu operatsiyani Smart Object yordamida qanday to&#39;g&#39;ri bajarish kerak?</p><p><strong>Yechim:</strong></p><ol><li>Qahramon qatlamini masshtablashdan oldin qatlam ustiga sichqonchaning o&#39;ng tugmasi bosiladi va <code>Convert to Smart Object</code> buyrug&#39;i tanlanadi (qatlam burchagida Smart Object belgisi paydo bo&#39;ladi).</li><li><code>Ctrl + T</code> bosilib, o&#39;lcham 50x50 pikselga kichraytiriladi.</li><li>Keyinchalik yana <code>Ctrl + T</code> bosilib, o&#39;lcham bemalol 600x600 pikselgacha kattalashtiriladi. Asl ma&#39;lumotlar konteyner ichida saqlangani sababli, oddiy rastrdan farqli o&#39;laroq tasvir o&#39;zining dastlabki tiniqligini to&#39;liq saqlab qoladi.</li></ol><h3 id="_2-topshiriq-clipping-mask-orqali-sehrli-qalqon-yaratish-o-rta" tabindex="-1">2-topshiriq. Clipping Mask orqali sehrli qalqon yaratish (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-clipping-mask-orqali-sehrli-qalqon-yaratish-o-rta" aria-label="Permalink to &quot;2-topshiriq. Clipping Mask orqali sehrli qalqon yaratish (o&#39;rta)&quot;">​</a></h3><p>O&#39;yin qahramonining dumaloq shakldagi qalqon qatlami (Shield) mavjud. Qalqon ustiga kosmik yulduzlar galaktikasi teksturasini va chetidan yaltirab o&#39;tuvchi yorug&#39;lik nurini qalqon doirasidan tashqariga chiqarmasdan qanday joylashtirish mumkin?</p><p><strong>Yechim:</strong></p><ol><li>Qalqon qatlami (Layer: <code>Shield</code>) pastda turadi.</li><li>Uning ustiga yangi qatlamda kosmik galaktika teksturasi rasmi joylashtiriladi (Layer: <code>Galaxy_Texture</code>).</li><li><code>Galaxy_Texture</code> qatlami ustiga sichqonchaning o&#39;ng tugmasi bosilib, <code>Create Clipping Mask</code> (yoki klaviaturada <code>Ctrl + Alt + G</code>) bosiladi. Natijada tekstura qalqonning dumaloq chegarasi bilan cheklanadi.</li><li>Uning ustidan yana bitta bo&#39;sh qatlam ochiladi va unga ham Clipping Mask beriladi. Oq yumshoq mo&#39;yqalam bilan nur chizilib, rejimi <code>Screen</code> yoki <code>Overlay</code> ga o&#39;tkaziladi.</li></ol><h3 id="_3-topshiriq-4-xil-assetdan-2d-o-yin-sahnasi-kollajini-yig-ish-qiyin" tabindex="-1">3-topshiriq. 4 xil assetdan 2D o&#39;yin sahnasi kollajini yig&#39;ish (qiyin) <a class="header-anchor" href="#_3-topshiriq-4-xil-assetdan-2d-o-yin-sahnasi-kollajini-yig-ish-qiyin" aria-label="Permalink to &quot;3-topshiriq. 4 xil assetdan 2D o&#39;yin sahnasi kollajini yig&#39;ish (qiyin)&quot;">​</a></h3><p>Sizda 4 ta alohida asset mavjud:</p><ul><li><ol><li>Qorong&#39;i g&#39;or foni;</li></ol></li><li><ol start="2"><li>Toshli zamin platformasi;</li></ol></li><li><ol start="3"><li>Sehrgar qahramon;</li></ol></li><li><ol start="4"><li>Sehrli ko&#39;k kristall. Ushbu elementlardan foydalanib, qahramon kristallga yaqinlashganda uning yuzi va zamin ko&#39;k nur bilan yorishadigan yaxlit kollaj yaratish bosqichlarini tasvirlang.</li></ol></li></ul><p><strong>Yechim:</strong></p><ol><li><strong>Kompozitsiya:</strong> 1920x1080 xolstda pastki qatlamga <code>G&#39;or foni</code>, o&#39;rtaga <code>Toshli zamin</code>, zamin ustiga <code>Sehrgar</code>, zaminning o&#39;ng tomoniga esa <code>Sehrli ko&#39;k kristall</code> joylashtiriladi.</li><li><strong>Kontakt soyalari:</strong> Qahramon va kristall ostiga yangi qatlam ochiladi, rejimi <code>Multiply</code> qilinadi va to&#39;q binafsha/qora yumshoq cho&#39;tka bilan yerga tegib turgan nuqtalarga qattiqroq, atrofga tarqaluvchi mayin soya chiziladi.</li><li><strong>Kristall nuri:</strong> Kristall ustiga yangi qatlam ochilib, rejimi <code>Screen</code> yoki <code>Linear Dodge (Add)</code> ga o&#39;tkaziladi. Moviy-ko&#39;k yumshoq cho&#39;tka bilan kristall ustiga nur uriladi.</li><li><strong>Qahramonga nur tushirish:</strong> Sehrgar qatlamining ustiga yangi qatlam ochilib, qahramonga <code>Clipping Mask</code> qilinadi. Uning rejimi <code>Color Dodge</code> qilinadi va qahramonning kristallga qaragan o&#39;ng tomoniga ko&#39;k tusli nur akslari beriladi.</li><li><strong>Umumiy uyg&#39;unlashtirish:</strong> Barcha qatlamlarning eng yuqorisiga <code>Adjustment Layer -&gt; Color Lookup</code> yoki <code>Curves</code> qo&#39;shilib, butun sahnaning rangi yagona sovuq-mistik atmosferaga keltiriladi.</li></ol><hr>',14))]),i("div",k,[i("h2",b,[o(l,{name:"file-text"}),a[9]||(a[9]=t(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=r("<ol><li>Nima uchun qatlamni <code>Convert to Smart Object</code> ga aylantirish masshtablashda sifatni saqlaydi? <ul><li><em>Javob:</em> Chunki Smart Object asl fayl ma&#39;lumotlarini o&#39;zgarishsiz alohida ichki konteynerda saqlaydi, masshtablashda esa piksellar tashlab yuborilmaydi.</li></ul></li><li>Clipping Mask yaratishning tezkor klaviatura kombinatsiyasi qaysi? <ul><li><em>Javob:</em> <code>Ctrl + Alt + G</code> (Mac&#39;da <code>Cmd + Option + G</code>) yoki qatlamlar oralig&#39;iga <code>Alt</code> tugmasini bosib sichqoncha bilan bosish.</li></ul></li><li>Bir nechta tanlangan qatlamlarni bitta guruh papkasiga jamlash qaysi tugma bilan bajariladi? <ul><li><em>Javob:</em> <code>Ctrl + G</code> (Mac&#39;da <code>Cmd + G</code>).</li></ul></li><li>Qatlamlar ustiga umumiy rang berish va barcha assetlarni bitta atmosferaga keltirish uchun qaysi vosita ishlatiladi? <ul><li><em>Javob:</em> Sozlash qatlamlari (Adjustment Layers: Curves, Color Balance, Hue/Saturation).</li></ul></li></ol><hr>",2))]),i("div",p,[i("h2",v,[o(l,{name:"file-text"}),a[12]||(a[12]=t(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=r("<ul><li><strong>Tartibsiz qatlamlar:</strong> O&#39;quvchilar qatlamlarni nomlamasdan <code>Layer 1</code>, <code>Layer 2</code> ko&#39;rinishida 50 ta qatlam yig&#39;ib yuborishadi. Oqibatda qaysi detal qayerdaligini topish imkonsiz bo&#39;ladi. Har doim mantiqiy papkalarga ajratish (<code>Ctrl + G</code>) va nom berish shart.</li><li><strong>Soya berishni unutish:</strong> Assetlar shunchaki fon ustiga tashlanganda havoda muallaq turgandek ko&#39;rinadi (yomon kollaj). Obyekt zaminga &quot;o&#39;tirishi&quot; uchun uning ostiga doimo kontakt soyasi (Contact Shadow) chizilishi shart.</li><li><strong>Turli rang harorati (Disparate Lighting):</strong> Bir manbadan olingan qahramon issiq quyosh nurida, fon esa sovuq tunda bo&#39;lsa, kollaj sun&#39;iy ko&#39;rinadi. Adjustment Layers va Clipping Mask orqali barcha qatlamlar bitta rang haroratiga keltirilishi kerak.</li></ul>",1))])])}const A=s(h,[["render",f]]);export{T as __pageData,A as default};
